			</div>
			{% endif %}
			{% if total_reward %}
			<div class="modal__total_prize">
Вам будет нарахований подвійний кешбек на суму: {{ total_reward }} грн.
			</div>
			{% endif %}

if ($this->config->get('config_fortune') && $this->customer->isLogged()) {
	unset($this->session->data['free_cartrige']);
	$prize_query = $this->db->query("SELECT * FROM `" . DB_PREFIX . "customer_fortune_prize` WHERE customer_id = '" . (int)$this->customer->getId() . "' AND date_added > DATE_SUB(NOW(), INTERVAL 24 HOUR)");
	$date_start = new DateTime(date('Y-m-d H:i:s'));
	$date_start->setTime(00, 00, 01);
	$date_end = new DateTime(date('Y-m-d H:i:s'));
	$date_end->setTime(23, 59, 59);
	if ($prize_query->num_rows) {
	/*
		if ($prize_query->row['prize'] == 'double') {
			$this->db->query("UPDATE " . DB_PREFIX . "order SET prize = 'double' WHERE order_id = '" . (int)$order_id . "'");
			$this->db->query("DELETE FROM " . DB_PREFIX . "customer_fortune_prize WHERE customer_id = '" . (int)$this->customer->getId() . "' AND prize = 'double'");
		}
	*/
		if ($prize_query->row['prize'] == 'double') {
			$order_products = $this->getOrderProducts($order_id);
			foreach ($order_products as $order_product) {
				$this->db->query("UPDATE " . DB_PREFIX . "order_product SET prize = 'double' WHERE product_id = '" . (int)$order_product['product_id'] . "'");
			}
			$this->db->query("DELETE FROM " . DB_PREFIX . "customer_fortune_prize WHERE customer_id = '" . (int)$this->customer->getId() . "' AND prize = 'double'");
			$this->db->query("UPDATE `" . DB_PREFIX . "customer_fortune` SET used = (used + 1), date_used = NOW() WHERE customer_id = '" . (int)$this->customer->getId() . "' AND prize = 'double' AND date_added > '" . $date_start->format('Y-m-d H:i:s') ."' AND date_added <= '" . $date_end->format('Y-m-d H:i:s') ."'");
		}
		if ($prize_query->row['prize'] == 'socks') {
			$this->db->query("UPDATE " . DB_PREFIX . "order SET prize = 'socks' WHERE order_id = '" . (int)$order_id . "'");
			$this->db->query("DELETE FROM " . DB_PREFIX . "customer_fortune_prize WHERE customer_id = '" . (int)$this->customer->getId() . "' AND prize = 'socks'");
			$this->db->query("UPDATE `" . DB_PREFIX . "customer_fortune` SET used = (used + 1), date_used = NOW() WHERE customer_id = '" . (int)$this->customer->getId() . "' AND prize = 'socks' AND date_added > '" . $date_start->format('Y-m-d H:i:s') ."' AND date_added <= '" . $date_end->format('Y-m-d H:i:s') ."'");
		}
	}
}
